output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper must not move from an open corridor into a single-file shelf aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartEntrySingleFileAisle": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntrySingleFileAisle"
    }
  },
  {
    "id": "mouth_interaction_must_park_cart",
    "text": "At the mouth of an upper single-file aisle, interacting while holding a cart must be a cart-parking interaction.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "mouthInteractionWithoutParking": {
          "pre": {
            "and": [
              "upperAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "mouthInteractionWithoutParking"
    }
  },
  {
    "id": "park_only_at_upper_aisle_mouth",
    "text": "A cart may only be parked at the designated mouths of the upper single-file aisles.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "upperAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_after_leaving_single_file",
    "text": "After leaving a single-file shelf aisle back to its mouth without the cart, the shopper is obliged to retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "exitSingleFileToMouthNoCart": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "upperAisleMouth",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "exitSingleFileToMouthNoCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "parked_cart_must_be_for_single_file_visit",
    "text": "Whenever a shopper parks the cart, they are obliged to enter a single-file shelf aisle without it.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "inSingleFileWithoutCart": {
          "and": [
            "singleFileShelfAisle",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "inSingleFileWithoutCart"
    }
  },
  {
    "id": "no_cartless_travel_in_wide_aisles",
    "text": "Except in the entrance cart area or at an upper aisle mouth, shoppers are prohibited from travelling through wide aisles without their cart.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "gt": [
            "freeWidthH",
            1
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entranceCartZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          "wideAisle",
          {
            "not": "upperAisleMouth"
          },
          {
            "not": "entranceCartZone"
          }
        ]
      }
    }
  },
  {
    "id": "open_shelf_interactions_require_cart",
    "text": "Shelf interactions from ordinary open aisles must be performed while the shopper still has the cart.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfSide": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfSide",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
